import{_ as s,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第109–115课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第109–115课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第102–108课","link":"/life/english/new-concept/book-1/review-part-15"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第116–122课","link":"/life/english/new-concept/book-1/review-part-17"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第102–108课","link":"/life/english/new-concept/book-1/review-part-15"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第116–122课","link":"/life/english/new-concept/book-1/review-part-17"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-16.md","filePath":"life/english/new-concept/book-1/review-part-16.md"}'),a={name:"life/english/new-concept/book-1/review-part-16.md"};function i(r,e,l,h,p,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第109–115课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第109–115课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第109–115课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第109–115课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-109-·-much-many-的比较级" tabindex="-1">Lesson 109 · much/many 的比较级 <a class="header-anchor" href="#lesson-109-·-much-many-的比较级" aria-label="Permalink to &quot;Lesson 109 · much/many 的比较级 {#lesson-109-·-much-many-的比较级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This recipe needs less sugar than the old one.</p><h3 id="练习-1-108" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-108" aria-label="Permalink to &quot;练习 1 {#练习-1-108}&quot;">​</a></h3><p>选择 less/fewer：___ sugar.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> less</p><p><strong>解析：</strong> 按本课规则判断：much 与 many 的比较级都是 more；little 表不可数数量时比较级为 less；few 对应 fewer，用于可数复数。比较水量用 more/less water，比较杯子数量用 more/fewer cups。a little 也可修饰比较级，表示稍微，如 a little cheaper。many 与 much 的选择取决于名词可数性，不能根据中文“多”判断。</p></details><p><strong>表达迁移：</strong> 围绕“比较数量并表达程度”写两至三句，再读给同伴听。至少使用一次much/many 的比较级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This recipe needs less sugar than the old one. We used fewer paper cups this week.</p><p>Needs 与单数主语 this recipe 一致；less 修饰不可数 sugar，than the old one 比较两个配方。 Used 为过去式，fewer 修饰复数可数名词 paper cups；this week 在这里指本周已发生的用杯情况。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-109">回看本课</a></p><h2 id="lesson-110-·-much-many-的比较级" tabindex="-1">Lesson 110 · much/many 的比较级 <a class="header-anchor" href="#lesson-110-·-much-many-的比较级" aria-label="Permalink to &quot;Lesson 110 · much/many 的比较级 {#lesson-110-·-much-many-的比较级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We used fewer paper cups this week.</p><h3 id="练习-1-109" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-109" aria-label="Permalink to &quot;练习 1 {#练习-1-109}&quot;">​</a></h3><p>选择 less/fewer：___ paper cups.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> fewer</p><p><strong>解析：</strong> 按本课规则判断：much 与 many 的比较级都是 more；little 表不可数数量时比较级为 less；few 对应 fewer，用于可数复数。比较水量用 more/less water，比较杯子数量用 more/fewer cups。a little 也可修饰比较级，表示稍微，如 a little cheaper。many 与 much 的选择取决于名词可数性，不能根据中文“多”判断。</p></details><p><strong>表达迁移：</strong> 围绕“比较数量并表达程度”写两至三句，再读给同伴听。至少使用一次much/many 的比较级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We used fewer paper cups this week. This recipe needs less sugar than the old one.</p><p>Used 为过去式，fewer 修饰复数可数名词 paper cups；this week 在这里指本周已发生的用杯情况。 Needs 与单数主语 this recipe 一致；less 修饰不可数 sugar，than the old one 比较两个配方。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-110">回看本课</a></p><h2 id="lesson-111-·-形容词最高级" tabindex="-1">Lesson 111 · 形容词最高级 <a class="header-anchor" href="#lesson-111-·-形容词最高级" aria-label="Permalink to &quot;Lesson 111 · 形容词最高级 {#lesson-111-·-形容词最高级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This is the lightest laptop in the shop.</p><h3 id="练习-1-110" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-110" aria-label="Permalink to &quot;练习 1 {#练习-1-110}&quot;">​</a></h3><p>写最高级：light → ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> lightest</p><p><strong>解析：</strong> 按本课规则判断：在明确范围内比较三者或更多对象，常用 the + 最高级。短形容词常加 est，多音节常用 most。范围可用 in + 地点/群体或 of + 复数集合，如 the cheapest of the three。good 的比较级和最高级是 better、best。highest price 不等于 best choice，应把评价维度说清楚。</p></details><p><strong>表达迁移：</strong> 围绕“从多个型号中选择最合适的”写两至三句，再读给同伴听。至少使用一次形容词最高级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This is the lightest laptop in the shop. Of the three routes, this one is the most convenient.</p><p>The lightest 为最高级，in the shop 限定比较范围；laptop 是被选中的类别名词。 Of the three routes 提供三者范围；the most convenient 是多音节形容词最高级，one 指路线。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-111">回看本课</a></p><h2 id="lesson-112-·-形容词最高级" tabindex="-1">Lesson 112 · 形容词最高级 <a class="header-anchor" href="#lesson-112-·-形容词最高级" aria-label="Permalink to &quot;Lesson 112 · 形容词最高级 {#lesson-112-·-形容词最高级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Of the three routes, this one is the most convenient.</p><h3 id="练习-1-111" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-111" aria-label="Permalink to &quot;练习 1 {#练习-1-111}&quot;">​</a></h3><p>写最高级：convenient → ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> most convenient</p><p><strong>解析：</strong> 按本课规则判断：在明确范围内比较三者或更多对象，常用 the + 最高级。短形容词常加 est，多音节常用 most。范围可用 in + 地点/群体或 of + 复数集合，如 the cheapest of the three。good 的比较级和最高级是 better、best。highest price 不等于 best choice，应把评价维度说清楚。</p></details><p><strong>表达迁移：</strong> 围绕“从多个型号中选择最合适的”写两至三句，再读给同伴听。至少使用一次形容词最高级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Of the three routes, this one is the most convenient. This is the lightest laptop in the shop.</p><p>Of the three routes 提供三者范围；the most convenient 是多音节形容词最高级，one 指路线。 The lightest 为最高级，in the shop 限定比较范围；laptop 是被选中的类别名词。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-112">回看本课</a></p><h2 id="lesson-113-·-so-neither-简短附和" tabindex="-1">Lesson 113 · so/neither 简短附和 <a class="header-anchor" href="#lesson-113-·-so-neither-简短附和" aria-label="Permalink to &quot;Lesson 113 · so/neither 简短附和 {#lesson-113-·-so-neither-简短附和}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I enjoy hiking, and so does my sister.</p><h3 id="练习-1-112" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-112" aria-label="Permalink to &quot;练习 1 {#练习-1-112}&quot;">​</a></h3><p>补助动词：I enjoy hiking. So ___ my sister.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> does</p><p><strong>解析：</strong> 按本课规则判断：肯定附和用 So + 助动词或情态动词 + 主语，否定附和用 Neither + 助动词或情态动词 + 主语。I can swim 对应 So can I；I don&#39;t drive 对应 Neither do I。选择的助动词需匹配原句，不能全部用 am。none 表没有一个或一点，通常替代前文数量，不等于 not 这个副词。</p></details><p><strong>表达迁移：</strong> 围绕“表示双方情况相同以及数量为零”写两至三句，再读给同伴听。至少使用一次so/neither 简短附和，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I enjoy hiking, and so does my sister. I cannot skate, and neither can Tom.</p><p>第一分句 enjoy 为一般现在时；附和中的主语 my sister 为单数，因此用 so does，而不是 so do。 Cannot skate 是否定能力陈述；neither can Tom 用相同情态动词并倒装，表示汤姆也不能。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-113">回看本课</a></p><h2 id="lesson-114-·-so-neither-简短附和" tabindex="-1">Lesson 114 · so/neither 简短附和 <a class="header-anchor" href="#lesson-114-·-so-neither-简短附和" aria-label="Permalink to &quot;Lesson 114 · so/neither 简短附和 {#lesson-114-·-so-neither-简短附和}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I cannot skate, and neither can Tom.</p><h3 id="练习-1-113" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-113" aria-label="Permalink to &quot;练习 1 {#练习-1-113}&quot;">​</a></h3><p>补助动词：I cannot skate. Neither ___ Tom.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> can</p><p><strong>解析：</strong> 按本课规则判断：肯定附和用 So + 助动词或情态动词 + 主语，否定附和用 Neither + 助动词或情态动词 + 主语。I can swim 对应 So can I；I don&#39;t drive 对应 Neither do I。选择的助动词需匹配原句，不能全部用 am。none 表没有一个或一点，通常替代前文数量，不等于 not 这个副词。</p></details><p><strong>表达迁移：</strong> 围绕“表示双方情况相同以及数量为零”写两至三句，再读给同伴听。至少使用一次so/neither 简短附和，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I cannot skate, and neither can Tom. I enjoy hiking, and so does my sister.</p><p>Cannot skate 是否定能力陈述；neither can Tom 用相同情态动词并倒装，表示汤姆也不能。 第一分句 enjoy 为一般现在时；附和中的主语 my sister 为单数，因此用 so does，而不是 so do。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-114">回看本课</a></p><h2 id="lesson-115-·-复合不定代词" tabindex="-1">Lesson 115 · 复合不定代词 <a class="header-anchor" href="#lesson-115-·-复合不定代词" aria-label="Permalink to &quot;Lesson 115 · 复合不定代词 {#lesson-115-·-复合不定代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Someone is waiting at the side door.</p><h3 id="练习-1-114" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-114" aria-label="Permalink to &quot;练习 1 {#练习-1-114}&quot;">​</a></h3><p>填 be：Someone ___ waiting.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：someone、anyone、everyone、no one 指人，something、anything、everything、nothing 指事物。作主语时通常视作单数，后用 is/has 等。形容词修饰它们时放在后面，如 something useful。nothing 和 no one 已含否定意义，标准英语通常不再加 not。some/any 的选择仍要结合肯定、否定、请求等语境。</p></details><p><strong>表达迁移：</strong> 围绕“表达有人、无人和不确定对象”写两至三句，再读给同伴听。至少使用一次复合不定代词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Someone is waiting at the side door. There is nothing unusual in the box.</p><p>Someone 作主语按单数处理，因此用 is waiting；at the side door 表等候位置。 There is 引出 nothing；unusual 放在复合不定代词之后，nothing 已含否定，无需再加 not。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-115">回看本课</a></p>',60)])])}const u=s(a,[["render",i]]);export{d as __pageData,u as default};
